const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const beijing = ee.Geometry.Point([116.4074, 39.9042]);
    const shanghai = ee.Geometry.Point([121.4737, 31.2304]);
    const startDay = 217; // Day of year for Aug 5
    const endDay = 224; // Day of year for Aug 12

    // Function to process MODIS LST data
    const processLST = (image) => {
        // According to MODIS user guide, LST_Day_1km needs scaling.
        const lst = image.select('LST_Day_1km').multiply(0.02).subtract(273.15);
        // Using QC_Day bits 0-1 for Mandatory QA flags. 0='Good data quality'
        const quality = image.select('QC_Day');
        const qaMask = quality.bitwiseAnd(0b11).eq(0);
        return lst.updateMask(qaMask);
    };

    // Function to calculate LST anomaly for a given location
    const getAnomaly = async (location, locationName) => {
        const dataset = ee.ImageCollection('MODIS/061/MOD11A1');

        // Baseline: 2000-2012 for the specific week
        const baselineCol = dataset
            .filter(ee.Filter.calendarRange(2000, 2012, 'year'))
            .filter(ee.Filter.calendarRange(startDay, endDay, 'day_of_year'))
            .map(processLST);

        // Target: 2013 for the specific week
        const targetCol = dataset
            .filter(ee.Filter.date('2013-08-05', '2013-08-13'))
            .map(processLST);

        const baselineSize = baselineCol.size().getInfo();
        const targetSize = targetCol.size().getInfo();

        if (baselineSize === 0 || targetSize === 0) {
            console.log(`No images found for ${locationName}. Baseline: ${baselineSize}, Target: ${targetSize}`);
            return 'C1';
        }

        const baselineMean = baselineCol.mean();
        const targetMean = targetCol.mean();

        const reducerArgs = {
            reducer: ee.Reducer.mean().combine({
                reducer2: ee.Reducer.count(),
                sharedInputs: true
            }),
            geometry: location,
            scale: 1000,
            maxPixels: 1e9,
        };

        const baselineStats = baselineMean.reduceRegion(reducerArgs).getInfo();
        const targetStats = targetMean.reduceRegion(reducerArgs).getInfo();

        if (!baselineStats || !baselineStats.LST_Day_1km_mean || baselineStats.LST_Day_1km_count === 0 ||
            !targetStats || !targetStats.LST_Day_1km_mean || targetStats.LST_Day_1km_count === 0) {
            console.log(`No valid pixels for ${locationName}.`);
            return 'C2';
        }

        const baselineTemp = baselineStats.LST_Day_1km_mean;
        const targetTemp = targetStats.LST_Day_1km_mean;

        if (baselineTemp === null || targetTemp === null) {
            console.log(`Calculation failed for ${locationName} (result is null).`);
            return 'C3';
        }

        const anomaly = targetTemp - baselineTemp;
        console.log(`${locationName} Baseline LST (2000-12): ${baselineTemp.toFixed(2)} C`);
        console.log(`${locationName} Target LST (2013): ${targetTemp.toFixed(2)} C`);
        console.log(`${locationName} Anomaly: ${anomaly.toFixed(2)} C`);

        return anomaly;
    };

    try {
        const beijingAnomaly = await getAnomaly(beijing, 'Beijing');
        if (typeof beijingAnomaly === 'string') {
            console.log(beijingAnomaly); // C1, C2, or C3
            return;
        }

        const shanghaiAnomaly = await getAnomaly(shanghai, 'Shanghai');
        if (typeof shanghaiAnomaly === 'string') {
            console.log(shanghaiAnomaly); // C1, C2, or C3
            return;
        }

        console.log(`Final Comparison: Shanghai Anomaly (${shanghaiAnomaly.toFixed(2)} C) > Beijing Anomaly (${beijingAnomaly.toFixed(2)} C)?`);

        if (shanghaiAnomaly > beijingAnomaly) {
            console.log('A');
        } else {
            console.log('B');
        }
    } catch (e) {
        console.error(`An error occurred: ${e.message}`);
        console.log('D');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Initialization failed: ${e.message}`);
    console.log('D');
});
